import{_ as a,a as t,c as o,ac as r}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Django常见故障的定位顺序","description":"按403、缺表、反向路由、模板路径和SQLite锁区分原因。","frontmatter":{"title":"Django常见故障的定位顺序","description":"按403、缺表、反向路由、模板路径和SQLite锁区分原因。","showdocs":{"topics":[{"id":"python","title":"Python","link":"/topics/python/"}],"kind":"排错","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Django专题","summary":"按403、缺表、反向路由、模板路径和SQLite锁区分原因。","status":"active","related":[{"title":"Django 入门：项目、路由与请求链","link":"/programming/python/django-request-model","kind":"开发实践","scope":"general","audience":"general"},{"title":"Django ORM、表单约束与事务","link":"/programming/python/plus/subjects/django-data","kind":"知识专题","scope":"general","audience":"general"},{"title":"Django个人任务板完整实践","link":"/programming/python/plus/practice/django-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"Django个人任务板完整实践 · Django任务板完整工程包含哪些文件至全部工程文件与同源正文","link":"/programming/python/plus/practice/django-application-part-01","kind":"开发实践","scope":"general","audience":"general"},{"title":"Django个人任务板完整实践 · tasks/urls.py至版本与资料边界","link":"/programming/python/plus/practice/django-application-part-02","kind":"开发实践","scope":"general","audience":"general"}],"prev":{"text":"Python 性能诊断：时间、分配、存活与解释器边界","link":"/programming/python/base/advanced/performance"},"next":{"text":"FastAPI 故障分析：阻塞、校验、锁与事务结果","link":"/programming/python/plus/troubleshooting/fastapi-diagnostics"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Python 性能诊断：时间、分配、存活与解释器边界","link":"/programming/python/base/advanced/performance"},"next":{"text":"FastAPI 故障分析：阻塞、校验、锁与事务结果","link":"/programming/python/plus/troubleshooting/fastapi-diagnostics"}},"headers":[],"relativePath":"programming/python/plus/troubleshooting/django-diagnostics.md","filePath":"programming/python/plus/troubleshooting/django-diagnostics.md"}'),n={name:"programming/python/plus/troubleshooting/django-diagnostics.md"};function i(s,e,d,l,p,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="django常见故障的定位顺序" tabindex="-1">Django常见故障的定位顺序 <a class="header-anchor" href="#django常见故障的定位顺序" aria-label="Permalink to &quot;Django常见故障的定位顺序&quot;">​</a></h1><p>诊断对象是<a href="/programming/python/plus/practice/django-application#source-files">个人任务板完整工程</a>；先能识别tasks/urls.py、settings.py中的SQLite路径和带CSRF令牌的POST表单，再按症状定位。</p><p>这个例子使用 Django 5.2.18。记录请求方法、命名路由、登录状态和测试数据库路径，可以将同一个 HTTP 状态对应到具体的响应阶段。</p><h2 id="csrf-403" tabindex="-1">Django表单提交403怎样排查CSRF <a class="header-anchor" href="#csrf-403" aria-label="Permalink to &quot;Django表单提交403怎样排查CSRF {#csrf-403}&quot;">​</a></h2><p>遇到 403 先区分 CSRF 拒绝与权限逻辑：检查响应原因及服务日志，再确认 CSRF 中间件、POST 表单内隐藏字段、浏览器 Cookie 和同源地址。登录可能更新 CSRF secret，旧标签页表单应刷新再提交。不能以删除中间件作为修复。</p><p>HTTPS 反向代理环境还需核对外部 scheme、Host、Origin 与代理信任配置，不能无条件信任客户端提供的转发头。示例仅回环 HTTP，本轮没有代理或 HTTPS 实验。真实浏览器联调与部署 Cookie 策略仍待单独验证。</p><h2 id="missing-table" tabindex="-1">Django出现no such table应该检查什么 <a class="header-anchor" href="#missing-table" aria-label="Permalink to &quot;Django出现no such table应该检查什么 {#missing-table}&quot;">​</a></h2><p><code>no such table: tasks_task</code> 首先检查迁移是否存在并应用，再检查当前设置与数据库路径。最常见的误判是给另一个环境运行了迁移，当前进程却读取不同 SQLite 文件。不要为了消除错误先手动建表，手动建表会绕开迁移历史。</p><p>用 showmigrations 查看已应用状态、migrate --plan 查看计划，并核对 BASE_DIR 指向的文件；新环境初次 migrate 还会建立 auth/session 等内置表。仓库提供手写初始迁移，其有效性需要框架的漂移检查与真实迁移验证。本例已经在临时 SQLite 文件上验证了模型无迁移漂移，并从空库执行迁移。</p><h2 id="reverse-template" tabindex="-1">Django的NoReverseMatch和模板缺失怎样区分 <a class="header-anchor" href="#reverse-template" aria-label="Permalink to &quot;Django的NoReverseMatch和模板缺失怎样区分 {#reverse-template}&quot;">​</a></h2><p>NoReverseMatch 表示命名空间、名称或参数无法反向匹配，检查 tasks:edit 是否提供整数 pk；TemplateDoesNotExist 表示模板路径未被加载器找到，检查 TEMPLATES 的 DIRS、APP_DIRS 和大小写。两类错误发生在不同步骤，不应通过硬编码所有地址一起“修复”。</p><p>本例项目级模板放 templates/tasks 和 templates/registration，login 默认寻找 registration/login.html。模板中的 URL 名称逐项对应应用 urls.py；测试调用 reverse 可在未来真实测试时进一步发现漂移。静态文件名存在不能证明完整模板渲染成功。</p><h2 id="constraint-lock" tabindex="-1">Django重复标题和database is locked怎样处理 <a class="header-anchor" href="#constraint-lock" aria-label="Permalink to &quot;Django重复标题和database is locked怎样处理 {#constraint-lock}&quot;">​</a></h2><p>重复标题违反唯一约束，应回滚并向用户显示表单错误；<code>database is locked</code> 更可能是 SQLite 写锁争用或事务持续过久，两者不能统一当成输入重复。先收集异常类型、操作、事务范围、并发量和数据库后端，再决定缩短事务、排查长连接或选择服务型数据库。</p><p>本例只把 IntegrityError 转成保存冲突提示，不吞掉 OperationalError；未来生产日志应保留异常上下文而避免记录密码、会话 Cookie。切换数据库后必须重新验证大小写唯一性、迁移、并发写和事务测试，不能把 SQLite 的本地结果直接推广。</p><h2 id="diagnostic-table" tabindex="-1">按症状寻找最短证据链 <a class="header-anchor" href="#diagnostic-table" aria-label="Permalink to &quot;按症状寻找最短证据链 {#diagnostic-table}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>首先区分</th><th>最小核对点</th></tr></thead><tbody><tr><td>无法启动且缺少DJANGO_SECRET_KEY</td><td>配置输入问题</td><td>当前终端进程是否设置变量；示例不会读.env</td></tr><tr><td>首页反复跳转登录</td><td>会话未保留或用户未认证</td><td>Cookie、域名、session表、登录重定向目标</td></tr><tr><td>新增后列表没有对象</td><td>owner或state筛选</td><td>当前用户、done值、筛选参数，检查是否真的成功保存</td></tr><tr><td>200但数据库没新增</td><td>表单错误页面</td><td>字段错误和非字段错误，不只看HTTP状态</td></tr><tr><td>404编辑地址</td><td>路由不匹配或授权过滤</td><td>命名路由、整数pk、当前owner；不要对外泄露归属</td></tr><tr><td>405退出/删除</td><td>GET访问写操作</td><td>使用带token的POST表单</td></tr></tbody></table><p>定位时先记方法、路径、用户身份是否存在、表单错误和异常类型，避免把整个请求体、Cookie或密码写入日志。对于重复标题，可以记录约束相关的业务事件；对于数据库锁，需要记录事务时长和并发背景，不能不断重试掩盖根因。</p><h2 id="evidence-boundary" tabindex="-1">静态检查和真实验证分别能说明什么 <a class="header-anchor" href="#evidence-boundary" aria-label="Permalink to &quot;静态检查和真实验证分别能说明什么 {#evidence-boundary}&quot;">​</a></h2><p>若路由或模板出错，先以 <code>reverse</code> 检查命名路由，再让测试客户端请求页面并断言渲染内容。只检查模板文件存在不能发现反向路由参数拼错；只检查 HTML 标签配对也不能发现视图没有提供所需上下文。</p><p>在临时数据库上，任务板的六个测试覆盖了登录、对象归属、表单数据、方法限制和 CSRF 拒绝。若问题只出现在部署环境，再检查反向代理提供的 scheme、外部 Host、Cookie 属性以及数据库配置。</p><h2 id="exercise" tabindex="-1">独立练习 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;独立练习 {#exercise}&quot;">​</a></h2><p>登录成功后 POST 403、GET 列表缺表、页面报 NoReverseMatch：分别列一个优先检查项，避免共同套用“重装依赖”。</p><p>先写出判断依据，再核对下节。</p><h2 id="answers" tabindex="-1">参考解答 <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;参考解答 {#answers}&quot;">​</a></h2><p>403查token与Cookie，缺表查当前数据库路径和迁移，NoReverseMatch查命名空间及pk参数；三者的处理阶段不同。</p><h2 id="sources" tabindex="-1">版本与资料边界 <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;版本与资料边界 {#sources}&quot;">​</a></h2><p>教学版本为 Django 5.2.18。涉及迁移、锁竞争或登录行为的问题，应在与实际项目一致的数据库后端、配置和补丁版本上复核。</p><p><a href="https://docs.djangoproject.com/en/5.2/howto/csrf/" target="_blank" rel="noopener noreferrer">CSRF诊断</a>；<a href="https://docs.djangoproject.com/en/5.2/ref/databases/#sqlite-notes" target="_blank" rel="noopener noreferrer">SQLite说明</a>；<a href="https://docs.djangoproject.com/en/5.2/howto/deployment/checklist/" target="_blank" rel="noopener noreferrer">部署检查</a>。版本依据：<a href="https://www.djangoproject.com/download/" target="_blank" rel="noopener noreferrer">支持表</a>与<a href="https://docs.djangoproject.com/en/5.2/releases/5.2.18/" target="_blank" rel="noopener noreferrer">5.2.18发布页</a>。</p>',29)])])}const m=a(n,[["render",i]]);export{h as __pageData,m as default};
